import { useEffect, useState } from "react";
import { getStudentProfile } from "../api";
import { getUserId } from "../auth";
import toast from "react-hot-toast";

export default function StudentDashboard() {
  const [student, setStudent] = useState(null);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const id = getUserId();
        const res = await getStudentProfile(id);
        setStudent(res);
      } catch (err) {
        toast.error("Failed to load student profile");
      }
    };
    fetchData();
  }, []);

  if (!student) return <div className="p-4">Loading...</div>;

  return (
    <div className="p-6 max-w-4xl mx-auto">
      <h1 className="text-3xl font-bold mb-4">Welcome, {student.name}</h1>
      <p className="mb-2"><strong>Overall Score:</strong> {student.overall_score}</p>
      <p className="mb-2"><strong>Career Interests:</strong> {student.career_interests}</p>
      <p className="mb-4"><strong>Address:</strong> {student.address}</p>

      <h2 className="text-xl font-semibold mt-4">Course Scores</h2>
      <ul className="list-disc ml-6">
        {Object.entries(student.course_scores || {}).map(([course, score]) => (
          <li key={course}>{course}: {score}</li>
        ))}
      </ul>

      {student.matched_tutor ? (
        <div className="mt-6 p-4 bg-green-100 rounded">
          <h3 className="font-bold text-lg">Matched Tutor</h3>
          <p>Name: {student.matched_tutor.name}</p>
          <p>Contact: {student.matched_tutor.contact_info}</p>
        </div>
      ) : (
        <div className="mt-6 p-4 bg-yellow-100 rounded">
          <p>No tutor matched yet.</p>
        </div>
      )}
    </div>
  );
}
